def audit():
    ports = dict(PORTS)
    bb = json.loads((ROOT / "assets/data/content/bb-scripts.json").read_text())
    for name in bb["scripts"]:
        ports[f"resources/bb_scripts/{name}.gd"] = ("translated", ["src/bb_scripts.rs", "assets/data/content/bb-scripts.json"], "Static text/reference body exported by a strict-grammar parser and run by a native interpreter; references (stats, statuses, actions, counters) are emitted by id, their own rendering belongs to the singleton get_bb_container_data functions.")
    for n in ("anti_steal", "crit_chance", "life_steal", "tier_i_reward", "stance", "difficulity_progress", "mercenary", "silver", "thunder", "scout", "wisdom", "blitz", "critical_strike", "prowlers_strike", "item_set_token", "bastolic", "darkness", "attack_screen_interact_button", "attack_stat_container"):
        ports[f"resources/bb_scripts/{n}.gd"] = ("translated", ["src/bb_scripts.rs"], "Hand-ported function with explicit inputs for arguments/translations (script uses conditionals/translation reads outside the exported grammar).")
    ports["classes/utils/bb_code.gd"] = ("translated", ["src/bb_scripts.rs"], "Tag wrappers; Color.to_html(true) rounding verified against Godot 4.4.1.")
    ports["classes/objects/bb_script.gd"] = ("translated", ["src/bb_scripts.rs"], "Base class defaults are empty lists/maps; subclasses are exported scripts.")
    ports["classes/objects/bb_counter.gd"] = ("translated", ["src/bb_scripts.rs"], "Counter hint/display pieces carry set id and amount.")
    ports["classes/objects/bb_container_data.gd"] = ("partial", ["src/bb_scripts.rs"], "Piece enum covers text/color/stat/status/action/keyword/set/passive/counter references; full rich field set (images, tags, hover refs) is not modelled.")
    for path in sorted((SOURCE / "resources/stat_scripts").glob("*.gd")):
        name = path.relative_to(SOURCE).as_posix()
        runtime = path.stem in ("faith", "luck")
        note = "Upgrade rule (including inherited zero) checked against Godot-executed source."
        if runtime:
            note += " Runtime handler is wired in src/run/scripts.rs (not Godot-executed)."
            if path.stem == "luck":
                note += " Luck packet mutation exists in DamageData.roll_luck."
        ports[name] = ("partial" if runtime else "translated", ["src/stats/upgrades.rs"] + (["src/run/scripts.rs"] if runtime else []), note)

    paths = sorted(SOURCE.rglob("*.gd"))
    known = {path.relative_to(SOURCE).as_posix() for path in paths}
    assert set(ports) <= known, set(ports) - known
    assert set(EXCLUDED) <= known, set(EXCLUDED) - known
    rows = []
    for path in paths:
        name = path.relative_to(SOURCE).as_posix()
        text = path.read_text()
        if name.startswith("addons/"):
            status, targets, note = "excluded", [], "Godot addon excluded by user."
        elif name in EXCLUDED:
            status, targets, note = "excluded", [], EXCLUDED[name]
        else:
            status, targets, note = ports.get(name, ("pending", [], "Not translated yet; do not substitute guessed behavior."))
        for target in targets:
            assert (ROOT / target).is_file(), target
        rows.append({
            "source": name, "sha256": hashlib.sha256(text.encode()).hexdigest(),
            "functions": re.findall(r'^(?:static )?func (\w+)\(', text, re.M),
            "status": status, "rust_or_data": targets, "note": note,
        })
    return {"scope": "All recovered .gd files; .tscn excluded. Mixed scripts retain local behavior; addons/multiplayer excluded explicitly.",
            "status_meaning": __doc__.split("\n\n", 1)[1].strip(),
            "counts": dict(sorted(Counter(row["status"] for row in rows).items())), "scripts": rows}


def check_oracle_hashes():
    for artifact, probe in [("stat-upgrade", "probe_stat_upgrades"), ("rng", "probe_rng"), ("format", "probe_format"), ("market-quote", "probe_market_quote"), ("item", "probe_items"), ("inventory", "probe_inventory"), ("inventory-interactions", "probe_inventory_interactions"), ("battle-profile", "probe_battle_profile"), ("character-stats", "probe_character_stats"), ("character-items", "probe_character_items"), ("character-content", "probe_character_content"), ("item-catalog", "probe_item_catalog"), ("character-runtime", "probe_character_runtime"), ("character-vitals", "probe_character_vitals"), ("character-attack", "probe_character_attack"), ("processor-status", "probe_processor_status"), ("enemy-scaling", "probe_enemy_scaling"), ("battle", "probe_battle"), ("game-mode", "probe_game_modes")]:
        hashes = json.loads((ROOT / f"artifacts/{artifact}-source-hashes.json").read_text())
        for path, expected in hashes.items():
            actual = hashlib.sha256((SOURCE / path).read_bytes()).hexdigest()
            assert actual == expected, f"Stale {artifact} oracle for {path}; run python3 tools/{probe}.py"


if __name__ == "__main__":
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    args = parser.parse_args()
    check_oracle_hashes()
    result = audit()
    content = json.dumps(result, indent=2) + "\n"
    target = ROOT / "artifacts/script-ports.json"
    if args.check:
        if target.read_text() != content:
            raise SystemExit("Port ledger is stale; run python3 tools/audit_script_ports.py")
    else:
        target.write_text(content)
    print(f"{len(result['scripts'])} scripts: {result['counts']}")
